// Rotates the vector `a` to the left by `offset` and returns the rotated vector.
// For n = a.len(), output b satisfies: b[i] = a[(i + offset) % n] for all i in 0..n.
// Empty input returns empty output.
fn rotate(a: Vec<i32>, offset: usize) -> Vec<i32> {
    let n = a.len();
    if n == 0 {
        return Vec::new();
    }

    let k = offset % n;
    let mut b = Vec::with_capacity(n);

    for i in 0..n {
        // Compute (i + k) % n without risking overflow in i + k.
        let mut j = i + k;
        if j >= n {
            j -= n;
        }
        b.push(a[j]);
    }

    b
}

fn main() {
    // Basic sanity checks
    assert_eq!(rotate(vec![], 5), vec![]);
    assert_eq!(rotate(vec![1, 2, 3, 4], 0), vec![1, 2, 3, 4]);
    assert_eq!(rotate(vec![1, 2, 3, 4], 1), vec![2, 3, 4, 1]);
    assert_eq!(rotate(vec![1, 2, 3, 4], 3), vec![4, 1, 2, 3]);
    assert_eq!(rotate(vec![1, 2, 3, 4], 5), vec![2, 3, 4, 1]); // 5 % 4 == 1
}